<?php namespace Workspace; $p=$opsProject;$s=$opsSelected;$sid=$s?(int)$s['id']:null;$dt=fn($v)=>$v===null?'—':gmdate('Y-m-d H:i:s',(int)$v).' UTC';$fields=function(string $act,bool $service=true)use($p,$sid){formFields($act);echo '<input type="hidden" name="project_id" value="'.h($p).'">';if($service&&$sid!==null)echo '<input type="hidden" name="service_id" value="'.h($sid).'">';}; ?>
