<?php foreach(array_slice($opsTickets,0,50) as $ticket): ?><article class="inset"><h3>#<?= h($ticket['id']) ?> · <?= h($ticket['title']) ?></h3><p><?= h($ticket['requester']) ?> · <?= h($ticket['state']) ?> · <?= h($dt($ticket['created_at'])) ?></p><pre class="release-text"><?= h($ticket['description']) ?></pre><p><a href="<?= h(url('bots',['project'=>$p,'support'=>$ticket['id']])) ?>">Ответ и история доставки Bots</a></p><?php if($ticket['incident_id']!==null): ?><p><a href="<?= h(url('incidents',['project'=>$p,'id'=>$ticket['incident_id']])) ?>">Инцидент #<?= h($ticket['incident_id']) ?></a></p><?php endif ?>
