<?php if($ticket['incident_id']===null): ?><form method="post" class="inline"><?php $fields('ops.link') ?><input type="hidden" name="id" value="<?= h($ticket['id']) ?>"><input type="hidden" name="version" value="<?= h($ticket['version']) ?>"><label>Инцидент ID<input name="incident_id" type="number" min="1" required></label><button>Связать</button></form><?php endif ?>
<form method="post" class="inset"><?php $fields('ops.close') ?><input type="hidden" name="id" value="<?= h($ticket['id']) ?>"><input type="hidden" name="version" value="<?= h($ticket['version']) ?>"><label>Результат поддержки<textarea name="resolution" maxlength="4000" required></textarea></label><button>Закрыть запрос</button></form><?php endif ?></article><?php endforeach ?>
