<?php if($i['release_id']!==null): ?><a href="<?= h(url('releases',['project'=>$p,'id'=>$i['release_id']])) ?>">Выпуск #<?= h($i['release_id']) ?></a><?php endif ?> <?php if($i['deployment_id']!==null): ?><a href="<?= h(url('deployments',['project'=>$p])) ?>">Развёртывание #<?= h($i['deployment_id']) ?></a><?php endif ?>
